  seller_id uuid not null,
  source_car_id uuid,
  title text not null,
  description text,
  category text not null,
  subcategory text,
  condition text,
  price_cents integer not null,
  currency text default 'USD'::text not null,
  location text,
  compatibility_notes text,
  status text default 'active'::text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  shipping_cents integer default 0 not null,
  allows_collection boolean default false not null,
  sold_at timestamp with time zone,
  reserved_until timestamp with time zone,
  part_number text,
  view_count integer default 0 not null,
  removed_at timestamp with time zone,
  removed_reason text,
  grade text,
  condition_checklist jsonb,
  part_number_compact text generated always as (NULLIF(regexp_replace(lower(COALESCE(part_number, ''::text)), '[^a-z0-9]'::text, ''::text, 'g'::text), ''::text)) stored,
  shipping_mode text default 'flat'::text not null,
  weight_oz numeric(8,2),
  length_in numeric(6,2),
  width_in numeric(6,2),
  height_in numeric(6,2),
  brand text,
  part_miles integer,
  part_miles_unit text,
  brand_key text generated always as (lower(brand)) stored,
  show_offer_floor boolean default false not null,
  published_at timestamp with time zone,
  published_xact bigint
) with (fillfactor=90);

alter table public.listings enable row level security;

-- Comments
comment on column public.listings.part_number is 'Manufacturer part number, seller-entered. Not verified by the platform.';
comment on column public.listings.view_count is 'Public part-sheet loads, excluding the seller. Counts loads, not unique viewers.';
comment on column public.listings.brand is 'Who made the part. Prefilled from the mod or the importer, matched from the title otherwise, always editable.';
comment on column public.listings.part_miles is 'How far this part has been driven (M-7). Optional, used parts only.';
comment on column public.listings.part_miles_unit is 'mi | km for part_miles. Required when part_miles is set.';
comment on column public.listings.show_offer_floor is 'The seller chose to show their offer minimum on the listing (O-3). The amount itself is in listing_private_terms.';

-- Constraints
alter table public.listings add constraint listings_catalog_assignment CHECK ((category = ANY (ARRAY['performance'::text, 'engine'::text, 'exterior-body'::text, 'interior-lighting'::text, 'brakes-suspension'::text, 'wheels-tires'::text])) AND (subcategory IS NULL OR category = 'performance'::text AND (subcategory = ANY (ARRAY['exhaust'::text, 'intake'::text, 'turbo'::text, 'intercoolers'::text, 'tuning'::text, 'fueling'::text])) OR category = 'engine'::text AND (subcategory = ANY (ARRAY['internals'::text, 'drivetrain'::text, 'transmission'::text, 'engine-mounts'::text, 'maintenance'::text])) OR category = 'exterior-body'::text AND (subcategory = ANY (ARRAY['aero'::text, 'bumpers'::text, 'hoods'::text, 'spoilers'::text, 'mirrors-trim'::text])) OR category = 'interior-lighting'::text AND (subcategory = ANY (ARRAY['seats'::text, 'steering'::text, 'gauges'::text, 'headlights'::text, 'interior-trim'::text])) OR category = 'brakes-suspension'::text AND (subcategory = ANY (ARRAY['big-brake-kits'::text, 'pads-rotors'::text, 'coilovers'::text, 'sway-bars'::text, 'air-ride'::text])) OR category = 'wheels-tires'::text AND (subcategory = ANY (ARRAY['wheels'::text, 'tires'::text, 'spacers-hardware'::text, 'tpms'::text]))));
alter table public.listings add constraint listings_condition_check CHECK (condition = ANY (ARRAY['new'::text, 'like_new'::text, 'used'::text, 'for_parts'::text]));
alter table public.listings add constraint listings_condition_checklist_shape CHECK (condition_checklist IS NULL OR jsonb_typeof(condition_checklist) = 'object'::text);
alter table public.listings add constraint listings_currency_usd CHECK (currency = 'USD'::text);
alter table public.listings add constraint listings_grade_check CHECK (grade IS NULL OR (grade = ANY (ARRAY['a'::text, 'b'::text, 'c'::text])));
alter table public.listings add constraint listings_live_needs_photo TRIGGER DEFERRABLE INITIALLY DEFERRED;
alter table public.listings add constraint listings_part_miles_check CHECK (part_miles IS NULL OR part_miles >= 0 AND part_miles <= 2000000 AND (part_miles_unit = ANY (ARRAY['mi'::text, 'km'::text])));
alter table public.listings add constraint listings_pkey PRIMARY KEY (id);
alter table public.listings add constraint listings_price_ceiling CHECK (price_cents <= 100000000);
alter table public.listings add constraint listings_price_cents_check CHECK (price_cents >= 0);
alter table public.listings add constraint listings_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES public.profiles(id) ON DELETE CASCADE;
alter table public.listings add constraint listings_shipping_bounds CHECK (shipping_cents >= 0 AND shipping_cents <= 10000000);
alter table public.listings add constraint listings_shipping_mode_check CHECK (shipping_mode = ANY (ARRAY['flat'::text, 'drvn'::text, 'pickup_only'::text]));
alter table public.listings add constraint listings_shipping_mode_shape_check CHECK ((shipping_mode <> 'drvn'::text OR weight_oz > 0::numeric AND length_in > 0::numeric AND width_in > 0::numeric AND height_in > 0::numeric) AND (shipping_mode <> 'pickup_only'::text OR allows_collection AND shipping_cents = 0));
alter table public.listings add constraint listings_source_car_id_fkey FOREIGN KEY (source_car_id) REFERENCES public.cars(id) ON DELETE SET NULL;
alter table public.listings add constraint listings_status_check CHECK (status = ANY (ARRAY['draft'::text, 'active'::text, 'reserved'::text, 'paused'::text, 'sold'::text, 'archived'::text, 'removed'::text]));
alter table public.listings add constraint listings_text_bounds CHECK (char_length(title) >= 1 AND char_length(title) <= 140 AND char_length(COALESCE(description, ''::text)) <= 8000 AND char_length(COALESCE(compatibility_notes, ''::text)) <= 2000 AND char_length(COALESCE(location, ''::text)) <= 120);

